parameters.query:
SELECT COALESCE((
  SELECT decrypted_secret FROM vault.decrypted_secrets
   WHERE name = 'overname_webhook_token' LIMIT 1
), '') AS overname_token;

parameters.jsCode:
// Shared-secret gate + input validation for the order handover door.
// The secret lives in Vault (overname_webhook_token), not in this code: shipday_compensate
// reads its keys the same way.
const secret = $input.first().json.overname_token || '';
const hook = $('Overname Webhook').first().json;
const headers = hook.headers || {};
const body = hook.body || {};
const token = headers['x-overname-token'] || '';

// A missing Vault row is a real fault - the door is not configured - and throws.
if (!secret) throw new Error('overname webhook secret missing from vault');

// A WRONG token is answered, not thrown. Unusual for an auth failure, and right here for one
// reason: this door has exactly one caller, over a private tunnel, and the most likely failure
// in the whole rollout is the Step 1 value being copied by hand onto two machines and not
// matching. A generic 500 would have an operator debugging the tunnel and n8n instead of the
// value. If this door ever becomes reachable from anywhere else, that reasoning expires and
// this goes back to a 401/500 that says nothing.
// 'Not allowed' is the whole message: no echo of the token, no word on whether it was absent
// or merely wrong, no name of the Vault key. Nothing that helps someone who should not be here.
// Nothing below this line runs for an unauthenticated caller - not even input validation.
if (token !== secret) {
  return [{ json: { toegelaten: false, ok: false, reden: 'niet_toegelaten' } }];
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const LOC = /^LOC_[A-Z0-9_]{1,32}$/;

const action = String(body.action || '');
const canonicalId = String(body.canonical_id || '');
if (!UUID.test(canonicalId)) throw new Error('canonical_id is not a uuid');

if (action === 'check') {
  const kandidaten = Array.isArray(body.location_keys) ? body.location_keys.map(String) : [];
  if (!kandidaten.length) throw new Error('location_keys is empty');
  for (const k of kandidaten) if (!LOC.test(k)) throw new Error('bad location_key: ' + k);
  return [{ json: { toegelaten: true, action, canonical_id: canonicalId, location_keys: kandidaten } }];
}

if (action === 'move') {
  const target = String(body.target_location_key || '');
  if (!LOC.test(target)) throw new Error('bad target_location_key');
  // No van_naam: the name that rides onto the printed ticket is read from dim_location in
  // the move query. The caller does not get to write on a customer's ticket.
  return [{ json: { toegelaten: true, action, canonical_id: canonicalId, target_location_key: target } }];
}

throw new Error('unknown action: ' + action);

// Terminal node of the refused branch: its item IS the response body, at HTTP 200.
// See the reasoning in Authenticate & Route. Nothing is added here - no token, no hint about
// which half was wrong, no Vault key name.
return [{ json: { ok: false, reden: 'niet_toegelaten' } }];

// An unknown canonical_id is an ANSWER, not a crash. Throwing here would reach the caller as
// n8n's generic 500 envelope ({"message":"Error in workflow"}) with this node's text nowhere
// in it, so the OS could not tell "no such order" from "the door fell over".
// Check Candidates carries alwaysOutputData so this node still runs on an empty result.
const gevraagd = $('Authenticate & Route').first().json;
const rows = $input.all().filter(r => r.json && r.json.location_key);

if (!rows.length) {
  return [{ json: {
    ok: false,
    reden: 'order_bestaat_niet',
    canonical_id: gevraagd.canonical_id
  } }];
}

// ok on every row, so the caller branches on one field in both actions and both outcomes.
return rows.map(r => ({ json: { ok: true, ...r.json } }));

// A refusal is an expected outcome of this door, so it is answered, not thrown: a thrown error
// reaches the caller as n8n's generic 500 envelope ({"message":"Error in workflow"}) with this
// node's text nowhere in it, and the OS could never tell a refusal from a crash.
// The SQL already answers { ok: false, reden: 'niets_gewijzigd', huidige_status } when the
// order exists but was not movable. Zero rows means the order id itself is absent - the move
// node carries alwaysOutputData, so that arrives here as one empty item instead of skipping
// this node.
const gevraagd = $('Authenticate & Route').first().json;
const rows = $input.all().filter(
  r => r.json && Object.prototype.hasOwnProperty.call(r.json, 'ok'));

if (!rows.length) {
  return [{ json: {
    ok: false,
    reden: 'order_bestaat_niet',
    canonical_id: gevraagd.canonical_id,
    huidige_status: null
  } }];
}

return rows;
